DROP TABLE IF EXISTS `order_speciality`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_speciality` (
  `customer_id` varchar(20) DEFAULT NULL,
  `order_id` varchar(20) NOT NULL,
  `total_spend` double DEFAULT NULL,
  `fulfillment_time_min` double DEFAULT NULL,
  `customer_satisfaction` int DEFAULT NULL,
  PRIMARY KEY (`order_id`),
  KEY `fk_os_customer` (`customer_id`),
  CONSTRAINT `fk_os_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`),
  CONSTRAINT `fk_os_order` FOREIGN KEY (`order_id`) REFERENCES `order_table` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
